  Lemma kd_rw : forall SPo shi O n A cs, cobj LB LF SPo shi O n -> SP <= SPo -> Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) Xa ->
    (O + n <= B \/ B + k <= O) -> O <= A -> A + Z.of_nat (cells_size cs) <= O + n ->
    rw_cells bsegs mA A cs -> rw_cells bsegs mB A cs.
  Proof.
    intros SPo shi O n A cs C LE FA D H1 H2 K. eapply (xpres_rw_cells H); [exact XP| exact K|].
    eapply kd_xcr; [eapply cobj_sub; [exact C| exact H1| exact H2| lia]| lia| exact LE| | lia].
    eapply Forall_impl; [| exact FA]. intros [l h] Q. cbn [fst snd] in *. lia.
  Qed.

  Lemma kd_acc : forall SPo shi O n a j, cobj LB LF SPo shi O n -> (O + n <= B \/ B + k <= O) -> accessible mA a j -> O <= a -> a + j <= O + n ->
    accessible mB a j.
  Proof.
    intros SPo shi O n a j C D AC H1 H2. eapply (xpres_accessible H); [exact XP| exact AC|]. intros x Hx.
    eapply kd_xsh; [exact C| lia| exact D| lia].
  Qed.

