  (* [comment removed for export] *)
  Lemma kd_fields : forall SPo shi O n Fa S L ns ls em, cobj LB LF SPo shi O n -> SP <= SPo -> O <= Fa -> Fa + 48 <= O + n ->
    Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) Xa -> (O + n <= B \/ B + k <= O) ->
    AFieldsC mA Fa S L ns ls em -> AFieldsOwn LB em ->
    (forall e d, em !! e = Some d -> Forall (fun iv : Z * Z => e + esize d <= fst iv \/ snd iv <= e) Xa /\ (e + esize d <= B \/ B + k <= e)) ->
