  (* [comment removed for export] *)
  Lemma kd_mbuf : forall SPo shi O n b es insz, cobj LB LF SPo shi O n -> SP <= SPo -> O <= b -> b + 64 <= O + n ->
    Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) Xa -> (O + n <= B \/ B + k <= O) ->
    AMBufOwn LB es -> AMBuf mA b es insz ->
    (forall x sz, In (x, sz) es -> Forall (fun iv : Z * Z => x + mb_block_size sz <= fst iv \/ snd iv <= x) Xa /\ (x + mb_block_size sz <= B \/ B + k <= x)) ->
    AMBuf mB b es insz.
  Proof.
    intros SPo shi O n b es insz C LE H1 H2 FA D MOWN MB ME. pose proof MB as [(ls & C0 & C1 & DL & LC & EL & AOK & SH & AB) OK]. split; [| exact OK].
    assert (KO : forall A cs, b <= A -> A + Z.of_nat (cells_size cs) <= b + 64 -> rw_cells bsegs mA A cs -> rw_cells bsegs mB A cs).
    { intros A cs K1 K2 CC. eapply (kd_rw SPo shi O n); [exact C| exact LE| exact FA| exact D| lia| lia| exact CC]. }
    assert (KE : forall x sz A cs, In (x, sz) es -> x <= A -> A + Z.of_nat (cells_size cs) <= x + mb_block_size sz -> rw_cells bsegs mA A cs -> rw_cells bsegs mB A cs).
    { intros x sz A cs IN K1 K2 CC. destruct (MOWN x sz IN) as [p INb]. destruct (ME x sz IN) as [M1 M2].
      eapply (kd_rw SP AAPP_HI x (mb_block_size sz)); [apply cobj_of_aobj; eapply aobj_block; [exact INb| lia| lia]| lia| exact M1| exact M2| exact K1| exact K2| exact CC]. }
    exists ls. split; [apply KO; [clear; lia| cbn; clear; lia| exact C0]|]. split; [apply KO; [clear; lia| cbn; clear; lia| exact C1]|].
    split; [exact DL|]. split.
    { intros a nd La. destruct (LC a nd La) as [WF CC]. split; [exact WF|].
      destruct (mb_lnode_cases _ _ _ _ _ DL AOK La) as [->|(sz & IN)].
      - apply KO; [clear; lia| cbn; clear; lia| exact CC].
      - destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _). eapply (KE a sz); [exact IN| clear; lia| cbn; clear - S0 R1; lia| exact CC]. }
    split.
    { intros x sz IN. destruct (EL x sz IN) as [junk CC]. exists junk. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _).
      eapply (KE x sz); [exact IN| clear; lia| cbn [cells_size csize]; rewrite Nat.add_0_r, Nat2Z.inj_add, Z2Nat.id by (clear - S0 R1; lia); clear - S0 R1; cbn; lia| exact CC]. }
    split; [exact AOK|]. split.
    { intros x sz IN. destruct (MOWN x sz IN) as [p INb]. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _).
      eapply kd_addr; [exact INb| exact (proj2 (ME x sz IN))| clear - S0 R1; lia| exact (SH x sz IN)]. }
    eapply (kd_acc SPo shi O n); [exact C| exact D| exact AB| lia| lia].
  Qed.

  (* [comment removed for export] *)
  Lemma kd_sv : forall ptr len, ASvOwn LB mA ptr len ->
    (1 <= len -> Forall (fun iv : Z * Z => ptr + len <= fst iv \/ snd iv <= ptr) Xa /\ (ptr + len <= B \/ B + k <= ptr)) -> ASvOwn LB mB ptr len.
  Proof.
    intros ptr len [Z0|(L1 & p & cs & IN & CC & AD)] M; [left; exact Z0| right]. split; [exact L1|]. exists p, cs. destruct (M L1) as [M1 M2].
    split; [exact IN|]. split.
    - eapply (kd_rw SP AAPP_HI ptr len); [apply cobj_of_aobj; eapply aobj_block; [exact IN| lia| lia]| lia| exact M1| exact M2| lia
        | cbn [cells_size csize]; rewrite Nat.add_0_r, Z2Nat.id by lia; lia| exact CC].
    - eapply kd_addr; [exact IN| exact M2| lia| exact AD].
  Qed.
  Lemma kd_hdr : forall h, HdrOwnA LB mA h ->
    (1 <= hv_ml h -> Forall (fun iv : Z * Z => hv_mp h + hv_ml h <= fst iv \/ snd iv <= hv_mp h) Xa /\ (hv_mp h + hv_ml h <= B \/ B + k <= hv_mp h)) ->
    (1 <= hv_tl h -> Forall (fun iv : Z * Z => hv_tp h + hv_tl h <= fst iv \/ snd iv <= hv_tp h) Xa /\ (hv_tp h + hv_tl h <= B \/ B + k <= hv_tp h)) ->
    HdrOwnA LB mB h.
  Proof. intros h (O1 & O2 & R1 & R2) M1 M2. split; [exact (kd_sv _ _ O1 M1)|]. split; [exact (kd_sv _ _ O2 M2)|]. split; [exact R1| exact R2]. Qed.

  (* [comment removed for export] *)
  Lemma kd_blkX : forall p A n, In (p, A, n) LB -> 0 < n -> (A + n <= B \/ B + k <= A) ->
    Forall (fun iv : Z * Z => A + n <= fst iv \/ snd iv <= A) Xa ->
    Forall (fun iv : Z * Z => A + n <= fst iv \/ snd iv <= A) (Xa ++ (B, B + k) :: (sh B, sh B + nsh k) :: XS)
    /\ Forall (fun iv : Z * Z => sh A + nsh n <= fst iv \/ snd iv <= sh A) (Xa ++ (B, B + k) :: (sh B, sh B + nsh k) :: XS).
  Proof.
    intros p A n IN Np D FA.
    pose proof (ah_blocks H HH _ _ _ _ RH IN) as (R1 & R2 & R3 & R4 & R5 & R6 & R7). cbn in R1, R2, R3, R4, R5, R6, R7.
    pose proof (aapp_bounds _ _ R7 R3) as (A1 & A2 & A3 & A4 & A5). pose proof aceil_facts as (AF & _).
    pose proof (aapp_not_shadowland _ _ R7) as NS. pose proof (sh_ge_lowsh A ltac:(clear - A4; lia)) as L.
    pose proof (sh_nsh_high A n ltac:(clear - A4; lia) R3 ltac:(clear - A3; lia)) as U.
